-- ============================================
-- EVENTOS: eventos del calendario (ejemplo; cada usuario ve los suyos)
-- ============================================
CREATE TABLE IF NOT EXISTS "EVENTOS" (
    "ID_EVENTO" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_EVENTOS" PRIMARY KEY,
    "TITULO" VARCHAR(200) NOT NULL,
    "DESCRIPCION" VARCHAR(1000) NULL,
    "INICIO" TIMESTAMPTZ NOT NULL,
    "FIN" TIMESTAMPTZ NOT NULL,
    "TODO_EL_DIA" BOOLEAN NOT NULL DEFAULT FALSE,
    "COLOR" VARCHAR(20) NULL,
    "ID_USUARIO" INT NOT NULL CONSTRAINT "FK_EVENTOS_USUARIO" REFERENCES "USUARIOS" ("ID_USUARIO") ON DELETE CASCADE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    "FECHA_CREACION" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT "CHK_EVENTOS_FECHAS" CHECK ("FIN" >= "INICIO")
);
CREATE INDEX IF NOT EXISTS "IX_EVENTOS_USUARIO_INICIO" ON "EVENTOS" ("ID_USUARIO", "INICIO");
